-- Étapes détaillées des recettes communes (poissons et œufs) (durées, feu, °C, repères de cuisson), pour la fiche « pas à pas » et ses
-- minuteurs. Nouvelle version de chaque recette : la version en cours est recopiée (ingrédients, temps…), seules les étapes
-- changent (data/recipes/seed.json). Idempotent : rien n'est fait si la version portant cette note existe déjà.
do $do$
declare
  r record;
  rid uuid;
  cv public.recipe_versions;
  p jsonb;
begin
  for r in select key as slug, value as steps from jsonb_each($etapes${"saumon-papillote-courgettes-citron":["Préchauffer le four à 200 °C. Cuire le riz 11 min dans une grande casserole d'eau bouillante salée et l'égoutter.","Couper les courgettes en fines rondelles et les répartir sur 4 grandes feuilles de papier cuisson.","Poser un pavé de saumon sur chaque lit de courgettes, ajouter une rondelle de citron, un filet d'huile, du sel, du poivre et les herbes. Fermer les papillotes en repliant bien les bords.","Cuire 18 à 20 min à 200 °C : le saumon est cuit quand il se détache en lamelles et reste légèrement rosé au centre. Ouvrir les papillotes à table et servir avec le riz."],"saumon-creme-epinards":["Cuire le riz 11 min dans une grande casserole d'eau bouillante salée et l'égoutter.","Faire fondre le beurre à feu moyen dans une sauteuse. Faire tomber les épinards avec l'ail haché 3 min (8 min s'ils sont surgelés), jusqu'à ce que leur eau soit évaporée.","Ajouter la crème et la muscade, saler et laisser épaissir 5 min à feu doux.","Chauffer une poêle à feu moyen-vif avec un filet d'huile. Cuire le saumon 5 min côté peau, jusqu'à ce que la peau soit croustillante, puis 2 min de l'autre côté.","Servir le saumon sur les épinards, avec un trait de citron et le riz."],"truite-amandes-haricots-verts":["Cuire les pommes de terre 20 min à la vapeur. Cuire les haricots verts 10 min dans l'eau bouillante salée et les égoutter.","Faire dorer les amandes 2 à 3 min à feu moyen dans une poêle sèche en remuant (elles brûlent vite), puis les réserver.","Faire fondre le beurre à feu moyen dans la poêle. Cuire les pavés de truite 3 min de chaque côté, en commençant côté peau, et saler.","Arroser de jus de citron, parsemer d'amandes et servir avec les haricots verts et les pommes de terre."],"cabillaud-lit-ratatouille":["Couper la courgette, l'aubergine, le poivron et les tomates en dés d'1,5 cm, émincer l'oignon et hacher l'ail.","Chauffer l'huile à feu moyen dans une cocotte. Faire revenir l'oignon et le poivron 5 min, ajouter l'aubergine et la courgette et cuire 5 min.","Ajouter les tomates, l'ail et les herbes, saler. Couvrir et laisser mijoter 25 min à feu doux, jusqu'à ce que les légumes soient fondants.","Préchauffer le four à 200 °C. Verser la ratatouille dans un plat.","Poser le poisson sur les légumes, saler, arroser d'un filet d'huile et cuire 12 min à 200 °C : la chair doit être nacrée et se détacher en feuillets."],"poisson-pane-maison-puree-carottes":["Éplucher les carottes et les pommes de terre, les couper en morceaux et les cuire 20 min dans l'eau salée, jusqu'à ce qu'elles soient très tendres.","Préparer trois assiettes : la farine, l'œuf battu avec une pincée de sel, la chapelure. Passer chaque filet dans la farine, puis l'œuf, puis la chapelure en appuyant.","Chauffer l'huile à feu moyen dans une grande poêle. Dorer les filets 3 min de chaque côté, jusqu'à ce que la panure soit bien dorée, puis les poser sur du papier absorbant.","Égoutter les légumes et les écraser avec le beurre, saler. Servir avec le poisson et des quartiers de citron."],"gratin-poisson-poireaux":["Couper les poireaux en deux, bien les laver et les émincer. Les faire fondre 15 min à feu doux dans le beurre, à couvert, en remuant de temps en temps.","Ajouter la crème, saler, poivrer et laisser épaissir 2 min.","Préchauffer le four à 200 °C. Disposer le poisson en morceaux dans un plat, couvrir de poireaux à la crème et parsemer de fromage.","Gratiner 20 min à 200 °C. Pendant ce temps, cuire les pommes de terre 20 min à la vapeur et servir avec le gratin."],"pates-thon-tomate-olives":["Porter une grande casserole d'eau salée à ébullition. Émincer l'oignon et hacher l'ail.","Chauffer l'huile à feu moyen dans une sauteuse. Faire revenir l'oignon 3 min, ajouter l'ail 1 min, puis les tomates et l'origan. Laisser mijoter 10 min à feu doux.","Pendant ce temps, cuire les pâtes 9 à 11 min (temps du paquet).","Ajouter le thon égoutté et émietté et les olives à la sauce, réchauffer 2 min.","Égoutter les pâtes, les mélanger à la sauce et servir."],"salade-nicoise":["Cuire les pommes de terre 20 min dans l'eau salée. Dans une autre casserole d'eau bouillante, cuire les œufs 9 min, puis les plonger dans l'eau froide.","Cuire les haricots verts 8 min dans l'eau bouillante salée et les rafraîchir à l'eau froide pour qu'ils restent verts.","Écaler les œufs et les couper en quartiers, couper les tomates et les pommes de terre en quartiers.","Préparer la vinaigrette avec l'huile, le vinaigre et du sel.","Disposer la salade, les légumes, le thon émietté, les œufs, les olives et les anchois. Arroser de vinaigrette juste avant de servir."],"wraps-truite-fumee":["Mélanger le fromage frais avec le jus du demi-citron et la ciboulette ciselée.","Couper le concombre en bâtonnets fins, laver la salade.","Tartiner les wraps de fromage, ajouter la salade, le concombre et la truite fumée.","Rouler serré en rentrant les côtés, couper en deux en biais et servir."],"quiche-saumon-poireaux":["Préchauffer le four à 200 °C. Laver et émincer les poireaux, les faire fondre 10 min à feu doux dans le beurre.","Garnir un moule de pâte et la piquer à la fourchette. Répartir les poireaux et le saumon coupé en dés.","Battre les œufs et la crème, saler, poivrer, et verser sur la garniture.","Cuire 35 min à 200 °C, jusqu'à ce que la quiche soit dorée et que le centre ne tremble plus. Servir tiède avec la salade."],"curry-poisson-coco":["Cuire le riz 11 min dans une grande casserole d'eau bouillante salée et l'égoutter.","Chauffer l'huile à feu moyen dans une sauteuse. Faire revenir l'oignon et le poivron émincés avec le curry et le curcuma 5 min.","Ajouter le lait de coco et les tomates, saler et porter à frémissement.","Ajouter le poisson en gros morceaux et cuire 8 min à feu doux, sans faire bouillir, en remuant délicatement pour ne pas le briser.","Finir avec le jus du citron vert et la coriandre ciselée. Servir avec le riz."],"pates-sardines-citron-chapelure":["Cuire les spaghetti 9 à 11 min dans une grande casserole d'eau bouillante salée (temps du paquet).","Faire dorer la chapelure 2 min à feu moyen dans une cuillère d'huile, en remuant, puis la réserver.","Dans le reste d'huile, faire revenir l'ail haché 1 min à feu doux, ajouter les sardines émiettées, le zeste et le jus du citron, réchauffer 2 min.","Égoutter les pâtes en gardant un verre d'eau de cuisson. Les mélanger aux sardines avec un peu d'eau de cuisson, parsemer de persil et de chapelure (piment dans l'assiette des adultes)."],"poisson-four-pommes-de-terre-fenouil":["Préchauffer le four à 200 °C. Couper les pommes de terre et le fenouil en tranches de 3 mm.","Les mélanger avec l'huile, le thym, du sel et du poivre dans un plat, et cuire 25 min à 200 °C, jusqu'à ce que les pommes de terre commencent à dorer.","Poser le poisson sur les légumes, saler, ajouter des rondelles de citron et poursuivre 12 à 15 min à 200 °C : la chair doit être nacrée et se détacher en feuillets."],"linguine-crevettes-ail-persil":["Cuire les linguine 9 à 11 min dans une grande casserole d'eau bouillante salée (temps du paquet).","Pendant ce temps, chauffer l'huile à feu doux et faire revenir l'ail émincé 1 min sans le colorer.","Monter à feu moyen, ajouter les crevettes et les tomates cerises coupées en deux, cuire 3 min jusqu'à ce que les crevettes soient roses.","Ajouter le jus du citron, les pâtes égouttées, un peu d'eau de cuisson et le persil haché. Mélanger 1 min et servir (piment dans l'assiette des adultes)."],"curry-crevettes-coco":["Rincer le riz thaï et le cuire 12 min dans l'eau bouillante salée, puis l'égoutter.","Couper la courgette et le poivron en dés, râper le gingembre.","Chauffer l'huile à feu moyen dans une sauteuse. Faire revenir les légumes avec le curry et le gingembre 5 min.","Verser le lait de coco, saler et laisser frémir 5 min à feu doux.","Ajouter les crevettes et cuire 3 min, jusqu'à ce qu'elles soient roses. Finir avec le jus du citron vert et la coriandre, servir avec le riz."],"riz-cantonais-crevettes":["Si le riz n'est pas déjà cuit, le cuire 11 min dans l'eau bouillante salée, l'égoutter et l'étaler sur une assiette pour qu'il refroidisse.","Battre les œufs avec une pincée de sel. Les cuire en omelette fine 2 min à feu moyen dans une cuillère d'huile, la rouler et la couper en lanières.","Chauffer le reste de l'huile à feu vif dans un wok. Faire sauter les petits pois, les crevettes et le jambon en dés 3 min.","Ajouter le riz et la sauce soja, faire sauter 3 min à feu vif.","Ajouter l'omelette et l'oignon nouveau émincé, mélanger 2 min à feu vif et servir."],"salade-crevettes-avocat-pamplemousse":["Peler le pamplemousse à vif au couteau et prélever les suprêmes au-dessus d'un bol pour garder le jus.","Couper les avocats en dés et les arroser du jus du citron vert pour qu'ils ne noircissent pas.","Mélanger 3 cuillères de jus de pamplemousse avec l'huile et une pincée de sel.","Mélanger la salade, les crevettes, l'avocat et les suprêmes, arroser de sauce et servir avec le pain."],"tortilla-espagnole":["Éplucher les pommes de terre et les couper en fines rondelles de 3 mm, émincer l'oignon.","Chauffer l'huile à feu moyen dans une poêle de 24 cm. Ajouter pommes de terre et oignon, saler, couvrir et cuire 15 min à feu doux en remuant de temps en temps : ils doivent être tendres sans dorer.","Battre les œufs avec du sel dans un grand bol. Égoutter les pommes de terre (garder 1 cuillère d'huile) et les mélanger aux œufs.","Remettre la cuillère d'huile dans la poêle, verser la préparation et cuire 8 min à feu doux, jusqu'à ce que les bords soient pris.","Retourner la tortilla à l'aide d'une grande assiette et cuire 4 min de l'autre côté. Servir tiède avec la salade."],"shakshuka":["Émincer l'oignon et les poivrons, hacher l'ail.","Chauffer l'huile à feu moyen dans une grande poêle. Faire revenir l'oignon et les poivrons 8 min, ajouter l'ail, le cumin et le paprika et remuer 1 min.","Verser les tomates, saler et laisser épaissir 10 min à feu doux.","Creuser 6 puits dans la sauce, y casser les œufs, couvrir et cuire 6 à 8 min, jusqu'à ce que les blancs soient pris et les jaunes encore coulants.","Émietter la feta sur le dessus et servir aussitôt avec le pain."],"oeufs-cocotte-epinards":["Préchauffer le four à 180 °C et faire chauffer de l'eau pour le bain-marie.","Faire fondre le beurre à feu moyen et y faire tomber les épinards 3 min. Ajouter la moitié de la crème et la muscade, saler.","Répartir les épinards dans 4 ramequins, casser 2 œufs par ramequin, ajouter le reste de crème et le fromage.","Poser les ramequins dans un plat, verser de l'eau chaude à mi-hauteur et cuire 12 min à 180 °C : le blanc doit être pris et le jaune coulant.","Couper le pain en mouillettes, les griller et servir avec les œufs."],"frittata-courgettes-feta":["Préchauffer le four à 190 °C. Couper les courgettes en fines rondelles et émincer l'oignon rouge.","Chauffer l'huile à feu moyen dans une poêle allant au four. Faire revenir les courgettes et l'oignon 8 min, jusqu'à ce qu'ils soient tendres.","Battre les œufs, poivrer, verser sur les légumes, puis émietter la feta et ajouter le basilic ciselé.","Cuire 3 min à feu doux sur le feu pour saisir le dessous, puis enfourner 15 min à 190 °C, jusqu'à ce que le centre soit pris.","Laisser tiédir 5 min, découper en parts et servir avec la salade."],"quiche-poireaux":["Préchauffer le four à 200 °C. Laver et émincer les poireaux, les faire fondre 12 min à feu doux dans le beurre.","Garnir le moule de pâte, la piquer à la fourchette et étaler les poireaux.","Battre les œufs, la crème et la muscade, saler, verser sur les poireaux et parsemer de fromage.","Cuire 35 min à 200 °C, jusqu'à ce que la quiche soit dorée et que le centre ne tremble plus. Servir tiède avec la salade."],"oeufs-brouilles-avocat-tartines":["Écraser les avocats avec le jus du demi-citron et une pincée de sel.","Griller les tranches de pain 2 à 3 min.","Battre les œufs avec du sel. Faire fondre le beurre à feu doux, verser les œufs et cuire 3 à 4 min en remuant sans cesse à la spatule. Retirer du feu quand ils sont encore crémeux : ils finissent de cuire hors du feu.","Tartiner le pain d'avocat, ajouter les œufs brouillés, la ciboulette ciselée et les tomates cerises coupées en deux."],"omelette-champignons-salade":["Trancher les champignons. Les faire sauter 6 min à feu vif dans la moitié du beurre, jusqu'à ce qu'ils soient dorés, saler et réserver.","Battre les œufs avec la ciboulette ciselée et du sel.","Faire mousser le reste du beurre à feu moyen dans une grande poêle, verser les œufs et cuire 3 à 4 min en ramenant les bords vers le centre, jusqu'à ce que le dessus soit presque pris.","Garnir de champignons et de fromage, plier l'omelette en deux et servir avec la salade et le pain."]}$etapes$::jsonb) loop
    select id into rid from public.recipes where household_id is null and slug = r.slug;
    if rid is null or exists (select 1 from public.recipe_versions where recipe_id = rid and change_note = 'Étapes détaillées : durées, intensité du feu, température du four, repères de cuisson.') then
      continue;
    end if;
    select v.* into cv from public.recipe_versions v join public.recipes c on c.current_version_id = v.id where c.id = rid;
    p := jsonb_build_object(
      'name', cv.name, 'description', cv.description, 'servings', cv.servings, 'prep_min', cv.prep_min, 'cook_min', cv.cook_min,
      'rest_min', cv.rest_min, 'difficulty', cv.difficulty, 'meal_types', to_jsonb(cv.meal_types), 'main_protein', cv.main_protein,
      'cuisine', cv.cuisine, 'seasons', to_jsonb(cv.seasons), 'tags', to_jsonb(cv.tags), 'status', cv.status, 'steps', r.steps,
      'ingredients', (select jsonb_agg(jsonb_build_object('slug', i.slug, 'label', ri.label, 'quantity', ri.quantity, 'unit', ri.unit,
        'base_quantity', ri.base_quantity, 'base_unit', ri.base_unit, 'optional', ri.optional, 'scale', ri.scale_mode) order by ri.position)
        from public.recipe_ingredients ri left join public.ingredients i on i.id = ri.ingredient_id where ri.version_id = cv.id));
    perform private.insert_recipe_version(rid, p, 'Étapes détaillées : durées, intensité du feu, température du four, repères de cuisson.');
    update public.recipe_versions set created_by = null where recipe_id = rid and change_note = 'Étapes détaillées : durées, intensité du feu, température du four, repères de cuisson.';
  end loop;
end
$do$;
